namespace MmaManager.Core.Sim.Generation.Origins;

public static partial class OriginsChapters
{
    // ===================== ERA 3: TWO WORLDS (1998-2004) =====================
    private static OriginsChapter[] Era3() => new[]
    {
        C("second-centre-arenas", 3, "The Dome Nights", 60, 120, A("rounds-and-judges", "shinken-and-duelo-open"),
            "A promotion outside North America fills an arena of fifteen thousand or more.",
            First("HoldEventAbove", 15000),
            A(),
            A("A second centre of the sport: venues of fifteen thousand and more open in Japan; promotions there earn bigger gates and run their own house rules; its stars are known abroad."),
            N("{Org} fills {City}",
              "Fifteen thousand people, a roof lit like a stage and a ring the size of a small house: {Org} has staged the biggest night the sport has seen, in {City}, {Country}. {Founder} stands in the aisle and does not speak for a long moment. The crowd is not there for a bracket or a gym argument. It has come for a spectacle, with entrances, music and a single belt on the line. Wherever the sport goes next, it will be measured against this."),
            N("{Org} sells out an arena in {City}",
              "{Org} has put fifteen thousand people into an arena in {City}, {Country}, a number no promotion in North America has come near. The show had lights, banners and a ring-walk that lasted longer than some bouts. Rival promoters flew in to look. They came home with a new word in their vocabulary: scale. Rival promoters flew in to look and flew home with the roof lighting rig on their wish lists."),
            N("A second centre of the sport",
              "{Year}. While the home promotions fight for small rooms, the sport finds a second home on the other side of the Pacific. In Tokyo, a promotion with a flair for theatre takes over a sports arena, then a dome, and fills it. The shows have entrances, orchestras and a ceremony as formal as a wedding. The champions of this second world are famous at home and unknown abroad, which is about to change."),
            "A second centre of the sport: Tokyo fills arenas of fifteen thousand and more."),

        C("first-cross-training-camp", 3, "The Room Where Everyone Learns Everything", 66, 114, A("style-upset"),
            "A camp's reputation passes a threshold because it teaches striking, wrestling and the ground together.",
            World("CampReputationAtLeast", 55),
            A(),
            A("Camps begin to teach a second and third discipline; fighters from a famous camp gain across disciplines instead of in one. Fenwick Street Combat Club is the first famous camp (see the scheduled arrivals)."),
            N("{Org}'s fighters come from the one room",
              "Every fighter on {Org}'s card now trains at the same gym, and the gym is the story. A boxer teaches wrestlers to punch; a wrestler teaches boxers to fall. {Fighter} walks to the ring knowing something that most of his opponents do not: how to lose a position and keep fighting. {Founder} signs everyone who emerges from that room. The camp is not a club any more. It is a school."),
            N("{Org} signs from the gym everyone is talking about",
              "A single gym is turning out fighters who can do three things instead of one, and {Org} has hired the best of them. {Fighter} is the proof: wrestling in the first round, striking in the second, submitting in the third. Rivals complain that it is unfair. It is simply earlier. Every other camp will have to learn the lesson or lose the argument."),
            N("The first famous gym",
              "{Year}. In a former tyre warehouse in the American Midwest, a coach with a boxer's hands and a wrestler's patience begins to teach all of it in one room. Students arrive from three states, then from other countries. They learn to punch, to take down, to submit, and to survive each in turn. Within two seasons its graduates are winning fights in every promotion in the world, and every ambitious gym is copying the timetable."),
            "The first famous camp: one room teaches striking, wrestling and the ground together."),

        C("specialists-fall", 3, "The Fall of the Specialists", 78, 132, A("first-cross-training-camp"),
            "Fighters who know more than one art begin to win most of their bouts against single-art specialists.",
            World("AllRoundersBeatSpecialists", 60),
            A(),
            A("The talent intake shifts: new fighters arrive trained in more than one discipline; single-art specialists age out and become rarer."),
            null, null,
            N("The age of the one-trick champion ends",
              "{Year}. Nobody announces it. A karate man loses to a wrestler who can punch; a judoka loses to a boxer who can defend a throw; a sumo veteran, unbeatable for a decade, finds that everyone has learned how to move him. The famous names of the early shows fade from the posters and a new kind of fighter takes their place: not the best at one thing, but good at all of them. The specialists do not vanish. They become the older generation, whose stories are better than their records."),
            "The specialists fall: fighters who know several arts beat those who know one.",
            "A world shift; no player variant."),

        C("scene-russia-australia-korea-sweden", 3, "Four More Scenes Wake", 66, 120, A("scene-britain-mexico"),
            "The first promotion to hold a card in one of these countries.",
            First("HoldEventInNewCountry"),
            A("CountryScene:RUS", "CountryScene:AUS", "CountryScene:KOR", "CountryScene:SWE"),
            A("The scenes in Russia, Australia, South Korea and Sweden wake; wrestling and sambo schools in Russia produce heavy talent; South Korea draws on taekwondo and ssireum."),
            N("{Org} opens a scene in {City}",
              "{Org} has taken the sport to {City}, {Country}, and the response was immediate: local gyms, local wrestlers and local sponsors, all asking when the next card will come. The first night sells out, the second adds a waiting list. {Founder} returns with a folder of names and a very short list of things that went wrong. Another country has discovered the sport; it will not give it back."),
            N("{Org} runs the first show in {City}",
              "{City}, {Country}, now has a scene. {Org} was first through the door, and the local newspapers are covering it as a curiosity. Rival promoters see an opportunity, not a curiosity: a country full of unrecognised talent and not a single competitor. The first fighters from the new scene will be signed within the season. The fighters on the bill are all local, all unpaid in advance and all very pleased to be asked."),
            N("Moscow, Sydney, Seoul and Stockholm",
              "{Year}. Four far-flung cities start to notice the sport in the same few years. In Russia, a generation of sambo and wrestling coaches realises its students have been preparing for this. In Australia, the surf-and-rugby crowds fill the first hall in a week. In South Korea, taekwondo and ssireum champions arrive from the national sports schools. In Sweden, a country of wrestlers and kickboxers realises it has been training for the sport without knowing."),
            "Scenes wake in Russia, Australia, South Korea and Sweden."),

        C("japan-network-weekly", 3, "Friday Night on Hokuto Television", 72, 132, A("second-centre-arenas"),
            "The first promotion to sign a weekly national-network television deal in its own country, outside North America.",
            First("SignMedia:ForeignNetwork"),
            A(),
            A("Promotions in that country earn broadcast fees and gain fame faster; the first network television the sport has seen."),
            N("{Org} goes weekly on {Partner}",
              "A network has taken a chance on {Org}: a weekly show, live from {City}, at an hour when families are home. {Founder} has spent a decade learning how to fill a hall and is now learning how to fill a living room. The cameras want faces, stories and entrances, and {Fighter} is happy to supply all three. The nation is, for the first time, watching a sport that never had a television home."),
            N("{Partner} signs {Org} for a weekly show",
              "{Partner} has committed to a weekly broadcast of {Org}'s cards from {City}, the sport's first network deal anywhere. The fee is serious. The audience is larger than any pay-per-view has produced. Promoters elsewhere, who have been scraping for late-night hours, are asking what the Japanese have that they do not. The commentators are former wrestlers, which was the network's idea, and the referee is a bow-tied veteran, which was the promoter's."),
            N("The first network season",
              "{Year}. In Japan, where professional wrestling has always filled living rooms on a Friday night, a television network decides to try the real thing in the same slot. Hokuto Television signs a weekly deal with the biggest promotion in the country. Families who once watched a scripted contest now watch the unscripted version, and the ratings are better than the network expected. A new economics of the sport has started: television pays, and television needs stars."),
            "The first network deal: Hokuto Television puts the sport on weekly in Japan."),

        C("first-supercard", 3, "Two Banners, One Ring", 78, 132, A("first-weight-split"),
            "The first two promotions to co-promote a single card with fighters from both.",
            First("CoPromote"),
            A("CoPromotion", "Crossovers"),
            A("Two promotions can co-promote a card; fighters can cross between promotions for a night."),
            N("{Org} shares the ring",
              "Rival promoters do not usually share anything, but {Org} and its biggest competitor have agreed to put on one card with two banners over the ring and a fighter from each side on every bout. {Founder} describes it as a business decision. The crowd calls it a first. It is the first time the sport's two best-known names are on the same poster, and the first time anyone has suspected that the sport might be bigger than any single room."),
            N("{Org} co-promotes the first supercard",
              "{Org} has joined forces with a rival to stage a joint card in {City}: half the fighters from each side, one gate, two sets of sponsors. There is a long list of conditions. There is also a long queue at the box office. If it works, there will be more. If it fails, nobody will admit it was their idea."),
            N("The first joint card",
              "{Year}. For years the sport's promotions have regarded one another as enemies. Now two of them agree on a truce for a night: a joint card, fighters from both sides, a single poster and a split of the money. The crowd, which has argued for years about which promotion has the best fighters, finally gets to see them meet. The precedent is quietly dangerous: once champions have fought for someone else's money, they know what they are worth."),
            "The first supercard: two promotions share a ring and a gate."),

        C("champion-vs-champion", 3, "Belt Against Belt", 96, 144, A("first-supercard"),
            "The first fight between the reigning champions of two different promotions.",
            First("ChampionVsChampion"),
            A("Superfights"),
            A("Champion-versus-champion superfights can be booked; the winner is acclaimed the best in the sport."),
            N("{Org}'s champion {Fighter} meets the other belt",
              "For years, every promotion has said its champion is the best in the world. {Org} has finally decided to find out. {Fighter} meets the other promotion's champion in {City}, with both belts on the table and a crowd that has waited years. {Founder} has told the press there is nothing to say. There is plenty to say after the final bell. For the first time, the argument has an answer."),
            N("{Org} sends {Fighter} to settle it",
              "{Fighter} of {Org} has agreed to defend a title against the champion of another promotion, the first such bout in the sport. The terms took six months and four lawyers. The result will decide a very old argument, and a great many bar bets. Whoever wins, the other promotion will want a rematch. Both promoters have agreed that the belts will stay where they are until the final bell."),
            N("The best against the best",
              "{Year}. Every title in the sport has, until now, meant only the best of its own promotion. In the biggest night the business has seen, the champions of two rival promotions agree to settle it in a single ring. The fighters know there is no safe way to do it. The promoters know the gate will be the biggest of the decade. For one evening the sport has a world title in everything but name."),
            "Belt against belt: the first champion-versus-champion fight."),

        C("scene-france-poland-thailand-argentina", 3, "Paris, Warsaw, Bangkok and Buenos Aires", 78, 132, A("scene-russia-australia-korea-sweden"),
            "The first promotion to hold a card in one of these countries.",
            First("HoldEventInNewCountry"),
            A("CountryScene:FRA", "CountryScene:POL", "CountryScene:THA", "CountryScene:ARG"),
            A("Scenes in France, Poland, Thailand and Argentina wake; Thailand brings its own kickboxing tradition, Poland a deep pool of strikers and grapplers."),
            N("{Org} opens the first scene in {City}",
              "{City}, {Country}, has its first card, and {Org} is behind it. The local fans know the arts: they have trained in them for generations. What they have not seen before is all of them in one ring. Tickets are gone in an afternoon. {Founder} walks the empty hall afterwards and notes down which local gyms to call first. Local newspapers send a photographer and a sceptic, and both come back converted."),
            N("{Org} is first into {City}",
              "{Org} has become the first promotion to hold a card in {City}, {Country}. A scene that did not exist a season ago now has a venue, a regular crowd and a waiting list of fighters. The home promotions will need to decide how much of the new talent to sign, and how soon. The first night's promoter, delighted and overworked, says he is already planning a second."),
            N("Four more flags go up",
              "{Year}. A new wave of cities decides it wants in. Paris fills a theatre with the first night in a country that has long argued over combat sport. Warsaw welcomes a crowd that knows every art on the card. Bangkok, whose kickboxing halls have run for generations, wonders why it took so long. Buenos Aires, with its street-corner wrestling and boxing gyms, joins in. The map of the sport spreads another quarter of the way round the world."),
            "Scenes wake in France, Poland, Thailand and Argentina."),

        C("sanction-spreads", 3, "The Commissions Fall in Line", 84, 132, A("first-sanctioned-state"),
            "A set number of regions have sanctioned the sport and the carriers stop distinguishing between them.",
            World("SanctionedRegionsAtLeast", 8),
            A(),
            A("Sanctioned regions spread across North America and Europe; the ban lifts region by region; PPV carriers come back for sanctioned promotions."),
            null, null,
            N("One licence becomes ten",
              "{Year}. The first licence was a curiosity. The second was a debate. By the tenth, commissions in a dozen regions have adopted nearly identical rules, shared their medical forms and begun to treat one another's approvals as binding. A promoter licensed in one region can now work in the next with a phone call instead of a lawsuit. The carriers, who left in a hurry, come back more slowly, with new contracts and new demands. The Backlash is over. It has left a rulebook behind."),
            "Sanctions spread region by region and the carriers return.",
            "A world shift; no player variant."),

        C("equipment-houses", 3, "Someone Sells the Gloves", 60, 108, A("gloves-adopted"),
            "The first promotion to sign an equipment maker.",
            First("SignSponsor:Equipment"),
            A("Sponsor:Equipment"),
            A("Equipment houses sponsor promotions that follow standard rules."),
            N("{Partner} outfits {Org}",
              "Every fighter on {Org}'s next card will wear gloves, shorts and a mouthguard supplied by {Partner}, which has paid for the privilege. {Founder} calls it the moment the sport became a market: a manufacturer has looked at the ring and seen a catalogue. The fighters get kit that fits. The fans get a logo to buy. The company gets something it has not had before: a sport that grows on its own."),
            N("{Partner} signs with {Org}",
              "{Partner}, a maker of training gear, has signed to supply {Org}'s cards in exchange for a logo on every glove. It is the first equipment deal in the sport. The money is modest. The signal is not: a company that makes things for athletes has decided this is a sport. Its founder, a retired boxer, has agreed to appear on the first poster in person, in shorts."),
            N("Gloves with a name on them",
              "{Year}. Once the rule requiring gloves is in place, somebody has to make them. A small maker of boxing gear, then a second company that sells training equipment to martial-arts schools, begin to compete for the contracts. The first deals trade free gear for logos. The second ones involve money. By the end of the year every serious promotion has a supplier, and every fighter has something to wear that is not borrowed."),
            "An equipment house signs on: the first gloves with a brand on them."),
    };
}
